namespace Service.Tests;

public sealed class CodeGeneratorTests
{
    [Theory]
    [InlineData(0, "0")]
    [InlineData(1, "1")]
    [InlineData(61, "Z")]
    [InlineData(62, "10")]
    [InlineData(3843, "ZZ")]
    [InlineData(3844, "100")]
    public void Encode_with_valid_id_returns_base62_string(long id, string expected)
    {
        string result = CodeGenerator.Encode(id);
        Assert.Equal(expected, result);
    }

    [Fact]
    public void Encode_with_zero_returns_zero_digit()
    {
        string result = CodeGenerator.Encode(0);
        Assert.Equal("0", result);
    }

    [Fact]
    public void Encode_with_negative_id_returns_zero_digit()
    {
        string result = CodeGenerator.Encode(-1);
        Assert.Equal("0", result);
    }

    [Fact]
    public void Encode_with_large_id_encodes_correctly()
    {
        long largeId = 1000000000000;
        string result = CodeGenerator.Encode(largeId);

        // Verify it's a valid base62 string (only alphanumeric)
        Assert.NotEmpty(result);
        Assert.True(result.All(c => char.IsLetterOrDigit(c)), "Result contains only alphanumeric characters");

        // Verify it's not just "0"
        Assert.NotEqual("0", result);

        // Verify encoding is deterministic
        string result2 = CodeGenerator.Encode(largeId);
        Assert.Equal(result, result2);
    }

    [Fact]
    public void Encode_with_sequential_ids_produces_distinct_codes()
    {
        string code1 = CodeGenerator.Encode(1);
        string code2 = CodeGenerator.Encode(2);
        string code3 = CodeGenerator.Encode(3);

        Assert.NotEqual(code1, code2);
        Assert.NotEqual(code2, code3);
        Assert.NotEqual(code1, code3);
    }
}
